import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BBXLvvRa.js";const u=JSON.parse('{"title":"Continuous Process Improvement","description":"Treat every automated process as a living product: measure it, assign lasting ownership, and iterate in small releases instead of stopping at go-live.","frontmatter":{"title":"Continuous Process Improvement","description":"Treat every automated process as a living product: measure it, assign lasting ownership, and iterate in small releases instead of stopping at go-live."},"headers":[],"relativePath":"docs/principles/continuous-improvement.md","filePath":"docs/principles/continuous-improvement.md"}'),n={name:"docs/principles/continuous-improvement.md"};function r(i,e,l,c,p,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="continuous-process-improvement" tabindex="-1">Continuous Process Improvement <a class="header-anchor" href="#continuous-process-improvement" aria-label="Permalink to &quot;Continuous Process Improvement&quot;">​</a></h1><blockquote><p>Continuous Process Improvement <strong>over</strong> Scoped and Time-Boxed Targets</p></blockquote><p><em>A process is a <a href="https://martinfowler.com/articles/products-over-projects.html" target="_blank" rel="noreferrer">living product, not a project</a> you finish and file away.</em></p><p>This principle asserts that automating a process is not a one-time deliverable. Business rules change, regulations shift, and the people who run the process learn what actually works. We hold this because an automated process is a product with a long life ahead of it, funded and staffed to evolve, not a project that ends the day it ships. The <a href="https://link.springer.com/book/10.1007/978-3-662-56509-4" target="_blank" rel="noreferrer">BPM lifecycle</a> captures this: process monitoring and controlling feeds straight back into identification and discovery, so improvement is a loop rather than a finish line.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>When you frame automation as a scoped, time-boxed project, you optimize for the go-live date and little beyond it. The classic failure mode is &quot;automate and forget&quot;: the process ships, the team disbands, and it is left to drift. Within months the model no longer matches how the business runs, workarounds appear, and trust in the system erodes.</p><p>The deeper cost is invisibility. A project that ends at go-live rarely measures what it built, so no one can answer basic questions. How long does a process instance take? Where do process instances pile up? Which decisions get overridden? Without measurement, you cannot tell an improvement from a regression, and every change becomes a guess.</p><p>Ownership is the other casualty. When budget and team dissolve at handover, a deployed process has no home. Incidents get patched reactively, technical debt accumulates in the Business Process Model and Notation (<a href="https://www.omg.org/spec/BPMN/" target="_blank" rel="noreferrer">BPMN</a>) and Decision Model and Notation (<a href="https://www.omg.org/spec/DMN/" target="_blank" rel="noreferrer">DMN</a>) models, and the next change costs far more than it should because no one remembers the design intent.</p><h2 id="in-practice" tabindex="-1">In practice <a class="header-anchor" href="#in-practice" aria-label="Permalink to &quot;In practice&quot;">​</a></h2><ul><li><strong>Assign a lasting process owner.</strong> Name a person accountable for the process after go-live, empowered to prioritize changes and set its direction.</li><li><strong>Instrument from day one.</strong> Track the numbers that reveal whether the process is improving, such as cycle time, throughput, and manual-override frequency, so you measure the process, not just monitor uptime. Techniques such as <a href="https://www.tf-pm.org/" target="_blank" rel="noreferrer">process mining</a> turn that event data into a picture of how the process actually runs.</li><li><strong>Define KPIs before you build.</strong> Agree on a few key performance indicators (the numbers that show whether the process serves its goal) and review them on a regular cadence.</li><li><strong>Close the feedback loop.</strong> Route insights from operations, task workers, and monitoring back into the model, and treat DMN decision tables as living artifacts that business experts can tune.</li><li><strong>Fund the product, not the project.</strong> Secure a standing budget and a small team for ongoing iteration instead of a single build grant that expires at launch.</li><li><strong>Ship small, iterate often.</strong> Deploy narrow, versioned changes to your BPMN process and validate each against your KPIs rather than banking every improvement into a rare big-bang release.</li></ul><h2 id="what-this-doesn-t-mean" tabindex="-1">What this doesn&#39;t mean <a class="header-anchor" href="#what-this-doesn-t-mean" aria-label="Permalink to &quot;What this doesn&#39;t mean&quot;">​</a></h2><p>Scope and deadlines still matter. Time-boxed targets give a team focus, force hard prioritization, and turn an open-ended ambition into something shippable. A first version of a claims-approval process has to go live before it can improve. The point is one of emphasis and sequencing: use scope to deliver a solid starting point, then keep investing, because the value of an automated process compounds over the improvements that follow.</p><h2 id="related-principles" tabindex="-1">Related principles <a class="header-anchor" href="#related-principles" aria-label="Permalink to &quot;Related principles&quot;">​</a></h2><ul><li><a href="/docs/principles/best-practices">Process Automation Best Practices</a>: instrumentation, CI/CD, and incremental releases make iteration safe.</li><li><a href="/docs/principles/business-it-alignment">Fostering Business-IT Alignment</a>: feedback from business and task workers, and DMN as living tables.</li></ul>',14)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
